// QA: 房间生成契约测试（S1）。断言 arch ADR-003 不变量。
// 若 game/js/gameplay/mapgen.js 未落盘，测试显式失败以暴露缺口，不掩盖。
import test from 'node:test';
import assert from 'node:assert/strict';

let mapgen = null;
try {
  mapgen = await import('../js/gameplay/mapgen.js');
} catch (e) {
  mapgen = null;
}

const hasGen = mapgen && typeof mapgen.generateFloor === 'function';

test('mapgen 模块存在且导出 generateFloor', () => {
  assert.ok(hasGen, 'game/js/gameplay/mapgen.js 缺失或未导出 generateFloor（集成缺口）');
});

test('同 seed + 同层号 → 房间图确定性一致', { skip: !hasGen }, () => {
  const a = mapgen.generateFloor({ seed: 12345, floorIndex: 1, chapter: 1 });
  const b = mapgen.generateFloor({ seed: 12345, floorIndex: 1, chapter: 1 });
  assert.deepEqual(a, b);
});

test('房间数 ∈ [8,12] 且存在 1 个 Boss 房', { skip: !hasGen }, () => {
  for (const seed of [1, 2, 3, 99, 12345]) {
    const f = mapgen.generateFloor({ seed, floorIndex: 1, chapter: 1 });
    const nonBoss = f.rooms.filter((r) => r.type !== 'boss');
    assert.ok(nonBoss.length >= 8 && nonBoss.length <= 12, `seed=${seed} 房间数=${nonBoss.length}`);
    assert.equal(f.rooms.filter((r) => r.type === 'boss').length, 1);
    assert.ok(f.bossRoomId);
  }
});

test('入口到 Boss 主路径连通', { skip: !hasGen }, () => {
  const f = mapgen.generateFloor({ seed: 7, floorIndex: 1, chapter: 1 });
  assert.ok(Array.isArray(f.mainPath) && f.mainPath.length >= 2);
  assert.equal(f.mainPath[f.mainPath.length - 1], f.bossRoomId);
  const ids = new Set(f.rooms.map((r) => r.id));
  for (const id of f.mainPath) assert.ok(ids.has(id), `主路径含未知房间 ${id}`);
});

test('每层恰好 1 篝火、1 商店', { skip: !hasGen }, () => {
  for (const seed of [1, 2, 3, 99, 12345]) {
    const f = mapgen.generateFloor({ seed, floorIndex: 1, chapter: 1 });
    assert.equal(f.rooms.filter((r) => r.type === 'campfire').length, 1, `seed=${seed}`);
    assert.equal(f.rooms.filter((r) => r.type === 'shop').length, 1, `seed=${seed}`);
  }
});

test('宝箱房 ∈ [2,4]', { skip: !hasGen }, () => {
  for (const seed of [1, 2, 3, 99, 12345]) {
    const f = mapgen.generateFloor({ seed, floorIndex: 1, chapter: 1 });
    const n = f.rooms.filter((r) => r.type === 'treasure').length;
    assert.ok(n >= 2 && n <= 4, `seed=${seed} 宝箱房=${n}`);
  }
});

test('钥匙门 ≤1 且无钥匙时主路径仍可达 Boss', { skip: !hasGen }, () => {
  for (const seed of [1, 2, 3, 99, 12345]) {
    const f = mapgen.generateFloor({ seed, floorIndex: 1, chapter: 1 });
    const keyDoors = f.rooms.filter((r) => r.locked).length;
    assert.ok(keyDoors <= 1, `seed=${seed} 钥匙门=${keyDoors}`);
    if (f.keyDoor) {
      assert.ok(!f.mainPath.includes(f.keyDoor.roomId), '钥匙门不应锁主路径');
    }
  }
});

// QA: 战斗契约测试（S2）。伤害公式、闪避无敌帧、技能CD、精英词缀。
import test from 'node:test';
import assert from 'node:assert/strict';

let combat = null;
try { combat = await import('../js/gameplay/combat.js'); } catch { combat = null; }
const hasCombat = combat && typeof combat.computeDamage === 'function';

test('combat 模块存在且导出 computeDamage', () => {
  assert.ok(hasCombat, 'game/js/gameplay/combat.js 缺失或未导出 computeDamage（集成缺口）');
});

test('伤害公式：基础伤害随攻击提升、随防御下降', { skip: !hasCombat }, () => {
  const base = combat.computeDamage({ attack: 10, defense: 0, crit: 0, qualityMul: 1 });
  const hiAtk = combat.computeDamage({ attack: 20, defense: 0, crit: 0, qualityMul: 1 });
  const hiDef = combat.computeDamage({ attack: 10, defense: 5, crit: 0, qualityMul: 1 });
  assert.ok(hiAtk > base);
  assert.ok(hiDef < base);
  assert.ok(base > 0);
});

test('暴击率 0 时无暴击、暴击率 1 时必暴击', { skip: !hasCombat }, () => {
  const noCrit = combat.computeDamage({ attack: 10, defense: 0, crit: 0, qualityMul: 1, rng: () => 0.99 });
  const alwaysCrit = combat.computeDamage({ attack: 10, defense: 0, crit: 1, qualityMul: 1, rng: () => 0.0 });
  assert.ok(alwaysCrit > noCrit);
});

test('闪避无敌帧：闪避期间不受伤', { skip: !hasCombat || typeof combat.isInvincible !== 'function' }, () => {
  const state = { dodging: true, dodgeTimer: 0.2 };
  assert.equal(combat.isInvincible(state), true);
  assert.equal(combat.isInvincible({ dodging: false, dodgeTimer: 0 }), false);
});

test('技能CD：冷却中不可释放，冷却结束可释放', { skip: !hasCombat || typeof combat.canCastSkill !== 'function' }, () => {
  assert.equal(combat.canCastSkill({ cdRemain: 1.0 }), false);
  assert.equal(combat.canCastSkill({ cdRemain: 0 }), true);
});

test('精英词缀生效：护盾/加速/分裂/吸血至少可识别', { skip: !hasCombat || typeof combat.applyEliteAffix !== 'function' }, () => {
  const e = { hp: 100, maxHp: 100, speed: 1, damage: 10 };
  const shielded = combat.applyEliteAffix(e, 'shield');
  assert.ok(shielded.shield > 0 || shielded.hp >= e.hp);
  const fast = combat.applyEliteAffix({ ...e }, 'haste');
  assert.ok(fast.speed >= e.speed);
});

// QA: 装备/掉落/强化契约测试（S3）。
import test from 'node:test';
import assert from 'node:assert/strict';

let items = null, loot = null;
try { items = await import('../js/gameplay/items.js'); } catch { items = null; }
try { loot = await import('../js/gameplay/loot.js'); } catch { loot = null; }
const hasItems = items && typeof items.generateItem === 'function';
const hasLoot = loot && typeof loot.rollQuality === 'function';

test('items/loot 模块存在', () => {
  assert.ok(hasItems, 'game/js/gameplay/items.js 缺失或未导出 generateItem');
  assert.ok(hasLoot, 'game/js/gameplay/loot.js 缺失或未导出 rollQuality');
});

test('装备 5 部位、2-4 词条', { skip: !hasItems }, () => {
  const slots = new Set();
  for (let i = 0; i < 200; i++) {
    const it = items.generateItem({ seed: i, slot: null, quality: 'blue' });
    slots.add(it.slot);
    assert.ok(it.affixes.length >= 2 && it.affixes.length <= 4, `词条数=${it.affixes.length}`);
  }
  for (const s of ['weapon', 'helmet', 'armor', 'boots', 'accessory']) {
    assert.ok(slots.has(s), `未生成部位 ${s}`);
  }
});

test('品质权重近似 白40/绿30/蓝20/紫8/橙2', { skip: !hasLoot }, () => {
  const counts = { white: 0, green: 0, blue: 0, purple: 0, orange: 0 };
  const N = 20000;
  for (let i = 0; i < N; i++) {
    const q = loot.rollQuality({ seed: i });
    counts[q] = (counts[q] || 0) + 1;
  }
  const pct = (k) => counts[k] / N;
  assert.ok(Math.abs(pct('white') - 0.40) < 0.03, `white=${pct('white')}`);
  assert.ok(Math.abs(pct('green') - 0.30) < 0.03, `green=${pct('green')}`);
  assert.ok(Math.abs(pct('blue') - 0.20) < 0.03, `blue=${pct('blue')}`);
  assert.ok(Math.abs(pct('purple') - 0.08) < 0.02, `purple=${pct('purple')}`);
  assert.ok(Math.abs(pct('orange') - 0.02) < 0.01, `orange=${pct('orange')}`);
});

test('Boss 保底蓝：Boss 掉落品质不低于 blue', { skip: !hasLoot || typeof loot.rollBossDrop !== 'function' }, () => {
  const order = { white: 0, green: 1, blue: 2, purple: 3, orange: 4 };
  for (let i = 0; i < 500; i++) {
    const q = loot.rollBossDrop({ seed: i });
    assert.ok(order[q] >= order.blue, `Boss 掉落 ${q} 低于蓝`);
  }
});

test('强化 +1~+9 失败不掉级', { skip: !hasItems || typeof items.enhance !== 'function' }, () => {
  let it = { enhanceLevel: 5 };
  for (let i = 0; i < 100; i++) {
    const r = items.enhance(it, { rng: () => 0.99 });
    it = r.item;
    assert.ok(it.enhanceLevel >= 5, '强化失败掉级');
    assert.ok(it.enhanceLevel <= 9);
  }
});

// QA: 存档契约测试（S4）。版本号、CRC、双备份、异常回退篝火。
import test from 'node:test';
import assert from 'node:assert/strict';

let save = null;
try { save = await import('../js/gameplay/save.js'); } catch { save = null; }
const hasSave = save && typeof save.serialize === 'function';

test('save 模块存在且导出 serialize/deserialize', () => {
  assert.ok(hasSave, 'game/js/gameplay/save.js 缺失或未导出 serialize');
  assert.ok(typeof save.deserialize === 'function');
});

test('序列化含版本号与 CRC', { skip: !hasSave }, () => {
  const data = { version: 1, worldSlot: 1, seed: 42, floorIndex: 1, player: { level: 1 }, inventory: [], gold: 0 };
  const s = save.serialize(data);
  assert.ok(s.version >= 1);
  assert.ok(typeof s.crc === 'string' || typeof s.crc === 'number');
});

test('往返序列化一致', { skip: !hasSave }, () => {
  const data = { version: 1, worldSlot: 1, seed: 42, floorIndex: 2, player: { level: 3 }, inventory: [{ id: 'x' }], gold: 100 };
  const s = save.serialize(data);
  const back = save.deserialize(s);
  assert.equal(back.seed, 42);
  assert.equal(back.gold, 100);
});

test('CRC 校验失败时回退到最近篝火', { skip: !hasSave || typeof save.loadWithFallback !== 'function' }, () => {
  const corrupted = { version: 1, seed: 42, crc: 'bad', lastCampfire: { floorIndex: 1, roomId: 'r1' } };
  const r = save.loadWithFallback(corrupted, { backup: null });
  assert.ok(r.fallback === true || r.roomId === 'r1');
});

// QA: 双人/多人缩放契约测试（S5）。
import test from 'node:test';
import assert from 'node:assert/strict';

let coop = null;
try { coop = await import('../js/gameplay/coop.js'); } catch { coop = null; }
const hasCoop = coop && typeof coop.getScaling === 'function';

test('coop 模块存在且导出 getScaling', () => {
  assert.ok(hasCoop, 'game/js/gameplay/coop.js 缺失或未导出 getScaling');
});

test('2/3/4 人缩放系数符合产品口径', { skip: !hasCoop }, () => {
  const s2 = coop.getScaling(2);
  assert.equal(s2.hp, 1.6); assert.equal(s2.dmg, 1.15); assert.equal(s2.gold, 1.25);
  const s3 = coop.getScaling(3);
  assert.equal(s3.hp, 2.1); assert.equal(s3.dmg, 1.25); assert.equal(s3.gold, 1.45);
  const s4 = coop.getScaling(4);
  assert.equal(s4.hp, 2.6); assert.equal(s4.dmg, 1.35); assert.equal(s4.gold, 1.65);
});

test('Boss 额外 +10% 血量', { skip: !hasCoop || typeof coop.getBossScaling !== 'function' }, () => {
  const b = coop.getBossScaling(2);
  assert.ok(Math.abs(b.hp - 1.6 * 1.1) < 1e-6);
});

test('扶起 3 秒', { skip: !hasCoop || typeof coop.reviveTime !== 'number' }, () => {
  assert.equal(coop.reviveTime, 3);
});

test('掉队 3 秒传送', { skip: !hasCoop || typeof coop.teleportDelay !== 'number' }, () => {
  assert.equal(coop.teleportDelay, 3);
});
